class Solution {
    public int longestSubarray(int[] nums){
        int maximum=Arrays.stream(nums).max().getAsInt(),current=0,answer=0;
        for(int value:nums){
            current=value==maximum?current+1:0;
            answer=Math.max(answer,current);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun longestSubarray(nums:IntArray):Int{
        val maximum=nums.maxOrNull()!!;
        var current=0;
        var answer=0;
        for(value in nums){
            current=if(value==maximum)current+1 else 0;
            answer=maxOf(answer,current)
        };
        return answer
    }
}

